<template>
  <section class="docs-shell">
    <header>
      <div><small>{{ $t('clinical360.documents.eyebrow') }}</small><h2>{{ $t('clinical360.documents.title') }}</h2><p>{{ $t('clinical360.documents.subtitle') }}</p></div>
      <div class="head-actions">
        <v-btn v-if="canFile" x-small outlined color="#0f766e" @click="openAttachment('scan')"><v-icon x-small left>mdi-scanner</v-icon>{{ $t('clinical360.documents.scan') }}</v-btn>
        <v-btn v-if="canFile" x-small outlined color="#0f766e" @click="openAttachment('upload')"><v-icon x-small left>mdi-upload-outline</v-icon>{{ $t('clinical360.documents.upload') }}</v-btn>
        <v-btn v-if="canFile" x-small depressed color="#0f766e" dark @click="$emit('file-document')"><v-icon x-small left>mdi-file-plus-outline</v-icon>{{ $t('clinical360.documents.new_note') }}</v-btn>
      </div>
    </header>
    <div class="toolbar"><v-text-field v-model="search" prepend-inner-icon="mdi-magnify" :label="$t('clinical360.documents.search')" dense outlined hide-details/><v-select v-model="category" :items="categories" :label="$t('clinical360.documents.category')" dense outlined hide-details/></div>
    <div class="docs-layout">
      <div class="docs-list">
        <button v-for="doc in filtered" :key="doc.id" :class="{active:selectedId===doc.id}" @click="selectedId=doc.id"><v-icon small>{{ doc.attachmentStorageKey?'mdi-paperclip':'mdi-file-document-outline' }}</v-icon><span><strong>{{ doc.title||$t('clinical360.documents.document') }}</strong><small>{{ categoryLabel(doc.category) }} · {{ format(doc.createdAt) }}</small></span><em>{{ doc.status||$t('clinical360.common.filed') }}</em></button>
        <p v-if="!filtered.length" class="empty">{{ $t('clinical360.documents.no_match') }}</p>
      </div>
      <article v-if="selected" class="doc-detail">
        <header><div><small>{{ categoryLabel(selected.category) }}</small><h3>{{ selected.title }}</h3></div><div class="detail-actions"><span>{{ selected.status||$t('clinical360.common.filed') }}</span><v-btn x-small text color="#0f766e" :loading="downloading" @click="downloadDocument(selected)"><v-icon x-small left>mdi-download-outline</v-icon>{{ $t('clinical360.common.download') }}</v-btn></div></header>
        <div v-if="selected.attachmentStorageKey" class="attachment-band"><v-icon color="#0f766e">{{ attachmentIcon(selected.attachmentType) }}</v-icon><div><strong>{{ selected.attachmentName }}</strong><small>{{ fileSize(selected.attachmentSize) }} · {{ $t('clinical360.documents.offline') }}</small></div><v-btn small depressed color="#0f766e" dark :loading="downloading" @click="downloadDocument(selected)"><v-icon small left>mdi-download-outline</v-icon>{{ $t('clinical360.common.download') }}</v-btn></div>
        <p>{{ selected.content||$t('clinical360.documents.no_text') }}</p><footer>{{ $t('clinical360.documents.filed_by', { date: format(selected.createdAt), author: selected.createdBy||'Clinical user' }) }}</footer>
      </article>
      <div v-else class="doc-detail empty">{{ $t('clinical360.documents.select') }}</div>
    </div>
    <input ref="scanInput" type="file" accept="image/*" capture="environment" hidden @change="selectFile">
    <input ref="uploadInput" type="file" accept="image/*,.pdf,.doc,.docx,.txt" hidden @change="selectFile">
    <v-dialog v-model="attachmentDialog" max-width="680" persistent scrollable>
      <v-card><v-card-title class="dialog-title"><div><small>{{ attachmentMode==='scan'?$t('clinical360.documents.camera_capture'):$t('clinical360.documents.file_import') }}</small><strong>{{ $t('clinical360.documents.add_title') }}</strong></div><v-spacer/><v-btn icon small @click="closeAttachment"><v-icon small>mdi-close</v-icon></v-btn></v-card-title>
        <v-card-text class="pt-4"><div class="form-grid"><v-text-field v-model="form.title" :label="$t('clinical360.documents.document_title')" dense outlined/><v-select v-model="form.category" :items="uploadCategories" :label="$t('clinical360.documents.category')" dense outlined/></div>
          <button type="button" class="drop-zone" @click="chooseFile"><v-icon size="36" color="#0f766e">{{ attachmentMode==='scan'?'mdi-camera-outline':'mdi-cloud-upload-outline' }}</v-icon><strong>{{ selectedFile?selectedFile.name:attachmentMode==='scan'?$t('clinical360.documents.open_camera'):$t('clinical360.documents.choose_file') }}</strong><span>{{ selectedFile?fileSize(selectedFile.size):$t('clinical360.documents.offline_hint') }}</span></button>
          <v-alert v-if="fileError" dense text type="error" class="mt-3">{{ fileError }}</v-alert><img v-if="previewUrl" :src="previewUrl" alt="Scanned document preview" class="scan-preview"><v-textarea v-model="form.note" :label="$t('clinical360.documents.description')" rows="3" dense outlined class="mt-3"/>
        </v-card-text><v-card-actions><v-spacer/><v-btn text small @click="closeAttachment">{{ $t('clinical360.common.cancel') }}</v-btn><v-btn small depressed color="#0f766e" dark :disabled="!selectedFile||!form.title" :loading="saving" @click="saveAttachment"><v-icon x-small left>mdi-content-save</v-icon>{{ $t('clinical360.documents.add_chart') }}</v-btn></v-card-actions></v-card>
    </v-dialog>
  </section>
</template>
<script>
import { getOfflineDocument, saveOfflineDocument } from '~/util/offline-document-storage'
export default {
  name:'Patient360DocumentsTab',
  props:{patientId:{type:String,required:true},documents:{type:Array,default:()=>[]},role:{type:String,default:''},readOnly:Boolean},
  data:()=>({search:'',category:'All',selectedId:'',attachmentDialog:false,attachmentMode:'upload',selectedFile:null,previewUrl:'',fileError:'',saving:false,downloading:false,form:{title:'',category:'Clinical Document',note:''}}),
  computed:{canFile(){return !this.readOnly&&['ADMIN','DOCTOR','NP','NURSE','MIDWIFE','RECORDS','FRONT_DESK'].includes(this.role)},categoryMap(){return{'Clinical Document':'clinical',Consent:'consent',Referral:'referral',Laboratory:'laboratory',Imaging:'imaging','Discharge Summary':'discharge',Education:'education','Wound Photo':'wound',Identification:'identification'}},uploadCategories(){return Object.keys(this.categoryMap).map(value=>({value,text:this.categoryLabel(value)}))},categories(){return[{value:'All',text:this.$t('clinical360.documents.categories.all')},...new Set(this.documents.map(x=>x.category||'Clinical Document'))].map(item=>typeof item==='string'?{value:item,text:this.categoryLabel(item)}:item)},filtered(){const q=this.search.toLowerCase();return this.documents.filter(x=>(this.category==='All'||(x.category||'Clinical Document')===this.category)&&`${x.title} ${x.category} ${x.content} ${x.attachmentName}`.toLowerCase().includes(q))},selected(){return this.documents.find(x=>x.id===this.selectedId)||this.filtered[0]||null}},
  methods:{
    format(v){return v?new Date(v).toLocaleString(this.$i18n.locale==='fr'?'fr-CM':'en-US'):'-'},categoryLabel(value){const key=this.categoryMap[value];return key?this.$t(`clinical360.documents.categories.${key}`):(value||this.$t('clinical360.documents.clinical_document'))},fileSize(n){if(!n)return this.$t('clinical360.documents.unknown_size');return n<1048576?`${Math.ceil(n/1024)} KB`:`${(n/1048576).toFixed(1)} MB`},attachmentIcon(t){return/pdf/i.test(t||'')?'mdi-file-pdf-box':/image/i.test(t||'')?'mdi-file-image-outline':'mdi-file-outline'},
    openAttachment(mode){this.attachmentMode=mode;this.attachmentDialog=true;this.$nextTick(this.chooseFile)},chooseFile(){const input=this.$refs[this.attachmentMode==='scan'?'scanInput':'uploadInput'];if(input)input.click()},
    selectFile(event){const file=event.target.files&&event.target.files[0];if(!file)return;this.fileError='';if(file.size>25*1048576){this.fileError=this.$t('clinical360.documents.max_size');return}this.selectedFile=file;if(!this.form.title)this.form.title=file.name.replace(/\.[^.]+$/,'');if(this.previewUrl)URL.revokeObjectURL(this.previewUrl);this.previewUrl=/^image\//.test(file.type)?URL.createObjectURL(file):''},
    closeAttachment(){this.attachmentDialog=false;this.selectedFile=null;this.fileError='';this.form={title:'',category:'Clinical Document',note:''};if(this.previewUrl)URL.revokeObjectURL(this.previewUrl);this.previewUrl='';if(this.$refs.scanInput)this.$refs.scanInput.value='';if(this.$refs.uploadInput)this.$refs.uploadInput.value=''},
    async saveAttachment(){if(!this.selectedFile||!this.form.title)return;this.saving=true;try{const key=`DOCFILE-${this.patientId}-${Date.now()}-${Math.random().toString(36).slice(2,8)}`;await saveOfflineDocument(key,this.selectedFile);await this.$store.dispatch('clinical/createDocument',{patientId:this.patientId,title:this.form.title,category:this.form.category,content:this.form.note,status:'Filed',captureMethod:this.attachmentMode,attachmentStorageKey:key,attachmentName:this.selectedFile.name,attachmentType:this.selectedFile.type||'application/octet-stream',attachmentSize:this.selectedFile.size});this.closeAttachment();this.$emit('saved',this.$t('clinical360.documents.save_success'))}catch(e){this.fileError=this.$t('clinical360.documents.storage_error')}finally{this.saving=false}},
    async downloadDocument(doc){this.downloading=true;try{const blob=doc.attachmentStorageKey?await getOfflineDocument(doc.attachmentStorageKey):new Blob([doc.content||doc.title||'Clinical document'],{type:'text/plain;charset=utf-8'});if(!blob)throw new Error('Missing file');const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=doc.attachmentName||`${String(doc.title||'document').replace(/[^a-z0-9_-]+/gi,'-')}.txt`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){if(this.$toast&&this.$toast.error)this.$toast.error(this.$t('clinical360.documents.unavailable'))}finally{this.downloading=false}}
  }
}
</script>
<style scoped>
.docs-shell{padding:14px;background:#f8fbfb;min-height:100%}.docs-shell>header{display:flex;justify-content:space-between;align-items:center;gap:16px;border-bottom:2px solid #0f766e;padding-bottom:10px}.docs-shell small{font-weight:900;color:#64748b}.docs-shell h2{font-size:18px;margin:2px 0}.docs-shell p{margin:0;font-size:12px}.head-actions{display:flex;gap:6px;flex-wrap:wrap}.toolbar{display:grid;grid-template-columns:2fr 1fr;gap:8px;margin:10px 0}.docs-layout{display:grid;grid-template-columns:minmax(280px,.85fr) 1.4fr;border:1px solid #cbd5e1;background:white;min-height:340px}.docs-list{border-right:1px solid #cbd5e1}.docs-list button{width:100%;display:grid;grid-template-columns:25px 1fr auto;gap:7px;text-align:left;padding:9px;border-bottom:1px solid #e2e8f0}.docs-list button.active{background:#e7f3f1;border-left:3px solid #0f766e}.docs-list span{display:flex;flex-direction:column}.docs-list small,.docs-list em{font-size:11px;color:#64748b}.doc-detail{padding:16px}.doc-detail>header{display:flex;justify-content:space-between}.doc-detail h3{font-size:16px}.doc-detail p{white-space:pre-wrap;margin-top:18px}.doc-detail footer{border-top:1px solid #e2e8f0;padding-top:10px;font-size:11px;color:#64748b}.attachment-band{display:grid;grid-template-columns:30px 1fr auto;align-items:center;gap:10px;background:#e7f3f1;border:1px solid #99c8c2;padding:10px;margin-top:14px}.attachment-band div{display:flex;flex-direction:column}.empty{padding:20px;color:#64748b}.dialog-title{font-size:15px!important;background:#e7f3f1}.dialog-title>div{display:flex;flex-direction:column}.form-grid{display:grid;grid-template-columns:1.3fr 1fr;gap:10px}.drop-zone{width:100%;min-height:125px;border:2px dashed #80b9b1;background:#f8fbfb;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px;padding:14px}.drop-zone span{font-size:12px;color:#64748b}.scan-preview{display:block;max-width:100%;max-height:280px;margin:12px auto;border:1px solid #cbd5e1}@media(max-width:700px){.docs-shell>header{align-items:flex-start;flex-direction:column}.docs-layout,.toolbar,.form-grid{grid-template-columns:1fr}.docs-list{border-right:0}.attachment-band{grid-template-columns:30px 1fr}.attachment-band .v-btn{grid-column:1/-1}}
</style>
